PB = [
("England", "OvenWorks commercial oven", "Maya runs a café in Bristol. Before contracting, she tells Daniel, OvenWorks Ltd's sales manager, that she needs an oven producing 120 pastries per hour and installation by 10 September for a booked launch. He emails: 'This model comfortably produces 120 pastries per hour, and we guarantee installation by 10 September.' Maya signs for £8,000 and pays £4,000. The contract identifies the model and installation date, and states in ordinary-sized print: 'The buyer confirms that it has not relied on any statement outside this agreement. OvenWorks accepts no liability for loss of profit arising from delay or equipment performance.' On 5 September OvenWorks demands another £1,500 because another customer will pay more for the slot. Maya cannot obtain another installer before launch and emails: 'I agree because I have no practical alternative, but I object to this extra charge.' Installation occurs on 15 September. Output is 70 pastries per hour; a pre-sale technical specification also records 70, but there is no evidence Daniel read it. Maya hires a temporary oven for £600 and claims £2,000 launch profit, partly estimated. Advise in approximately 700 words on claims, variation/duress, clauses and remedies. Use verified OSCOLA authorities and a grouped bibliography; do not assume fraud or apply consumer law to this business purchase."),
("England", "Consumer furniture", "Nina orders a £1,200 sofa online for personal use. It arrives with torn upholstery, and the retailer acknowledges the fault. Nina agrees to repair, which fails. The retailer offers a voucher and demands £150 collection costs. Nina also damaged a separate cushion after delivery. Analyse rights, proof, deductions and practical remedies in 700 words. Distinguish the original defect from later damage."),
("England", "Email formation and late acceptance", "Arun offers by email to sell specialist equipment to Bea for £6,000, stating acceptance must arrive by Friday noon. Bea emails acceptance at 11:58, but a server problem delays arrival until 12:20. At 12:05 Arun sells to Chen. Earlier Bea had asked whether payment could be split. Analyse formation, the effect of that question, receipt and remedies. Identify facts that would change the answer; 700 words."),
("England", "Advice and negligent loss", "A surveyor sends a report to a bank knowing it will be used for a named buyer's mortgage. The buyer relies on it too; a prominent notice disclaims responsibility to anyone but the bank. A serious structural defect is missed. The buyer claims repair costs and a later market fall. Analyse duty, scope, reliance, disclaimer and loss in 800 words."),
("England", "Dismissal after complaint", "Lena has worked for a company for ten months. She reports a suspected safety breach, is moved to undesirable shifts and dismissed for 'attitude'. An internal email refers to her complaint. The employer says a reorganisation was planned earlier. Analyse possible claims, qualifying conditions, causation, remedies and urgent steps without assuming every complaint is protected; 800 words."),
("Wales", "Housing disrepair and notice", "A Cardiff contract-holder repeatedly reports severe damp and a faulty electrical socket. The landlord sends a possession notice after a council inspection. The contract-holder has photographs and messages but has withheld one month's rent. Analyse the Welsh statutory framework, evidence, possession issues and remedies. State any missing material dates; 800 words."),
("New York, USA", "Employment and restrictive covenant", "A New York employee earning $70,000 signs a two-year nationwide non-compete and leaves for a competitor after dismissal. The employer seeks an injunction and alleges misuse of a customer list; the employee says the list is public. Analyse enforceability, trade-secret issues and remedies under current state/federal law, identifying facts requiring clarification. 800 words."),
("England and France", "Cross-border online sale", "A London consumer buys a camera from a French website actively advertising delivery to England. Terms select French law and French courts. The camera arrives defective and the seller refuses a refund. Analyse applicable law, jurisdiction and practical enforcement, distinguishing them carefully. Verify the current cross-border rules; approximately 900 words."),
]

def main():
    rows=[]
    for prefix, task, values in (("GE","general",GE),("ES","essay",ESSAYS),("PB","problem",PB)):
        for i,(jurisdiction,title,prompt) in enumerate(values,1):
            row={"id":f"{prefix}{i:02}","task_type":task,"jurisdiction":jurisdiction,
                 "as_of_date":DATE,"title":title,"question":f"Today is 23 September 2026. Jurisdiction: {jurisdiction}.\n\n{prompt}",
                 "word_target":700 if task!='general' else 450,
                 "selected_for_visible_run":(prefix=="GE" and i<=5) or (prefix=="ES" and i<=2) or (prefix=="PB" and i==1),
                 "status":"AUTHORED_EXPOSED_NOT_RUN","training_approved":False,"gold_answer":False}
            if prefix=="GE" and i==2:
                row['follow_up']="The flat is in Birmingham, England. I rent the entire flat as my main home. The landlord does not live there and has never shared the accommodation. The written agreement was for 1 September 2025 to 31 August 2026, and I continued living there and paying monthly since then. Rent is due on the first, and I have no arrears. The quoted email is the only notice; no prescribed form or attachment was sent. I have not agreed to move out. Continue using my earlier message."
            rows.append(row)
    assert len(rows)==50 and sum(row['selected_for_visible_run'] for row in rows)==8
    root=ROOT/'data/evaluations/visible-final-check-20260923'
    target=root/'PRACTICE-QUESTIONS-50.json'
    if target.exists(): raise RuntimeError('Preserve the authored question set')
    target.write_text(json.dumps({'schema':'legalbot.exposed-practice-bank.v1','purpose':'visible evaluation and non-weight improvement; no gold or training approval','counts':{'GE':30,'Essay':12,'PB':8},'questions':rows},indent=2,ensure_ascii=False)+'\n')
    md=['# LegalBot: 50 exposed practice questions','', '30 GE, 12 Essay and 8 PB. Eight are selected for this visible check. The remaining 42 are authored prompts, not completed tests. These questions are exposed development material, not an unseen validation set. No answer here is legal gold or approved fine-tuning data.','']
    for r in rows:
        md += [f"## {r['id']} — {r['title']}",'',f"Mode: {r['task_type']}. Visible run: {'selected' if r['selected_for_visible_run'] else 'not selected'}.",'',r['question'],'']
        if r.get('follow_up'):md += ['Follow-up (send only after clarification):','',r['follow_up'],'']
    (ROOT/'docs/testing/PRACTICE_QUESTIONS_50.md').write_text('\n'.join(md))
    print('Prepared 50 questions: 30 GE, 12 Essay, 8 PB; eight selected.')

if __name__=='__main__': main()
